package com.andye.warmod.phalanx;import java.util.UUID;import net.minecraft.world.phys.Vec3;public final class PhalanxBullet{public final UUID bulletId,turretId,targetId;public Vec3 position,previousPosition,velocity;public int age;public final long visualSeed;public PhalanxBullet(UUID bullet,UUID turret,UUID target,Vec3 position,Vec3 velocity,long seed){bulletId=bullet;turretId=turret;targetId=target;this.position=this.previousPosition=position;this.velocity=velocity;visualSeed=seed;}public void tick(){previousPosition=position;velocity=velocity.add(0,-PhalanxConstants.BULLET_GRAVITY_PER_TICK_SQUARED,0);position=position.add(velocity);age++;}}
